import*as t from"babel-types";export function runtimeProperty(e){return t.memberExpression(t.identifier("regeneratorRuntime"),t.identifier(e),!1)}export function isReference(e){return e.isReferenced()||e.parentPath.isAssignmentExpression({left:e.node})}export function replaceWithOrRemove(e,r){r?e.replaceWith(r):e.remove()}